async function runAI(){
  if(!state||replayMode||screen!=='battle'||state.mode!=='ai'||state.team!=='red'||state.winner||modal||runningAiEpoch===battleEpoch)return;
  const epoch=battleEpoch;runningAiEpoch=epoch;
  const current=()=>epoch===battleEpoch&&screen==='battle'&&!modal&&!replayMode&&state?.mode==='ai'&&state.team==='red';
  try{
    for(let i=0;i<18&&current()&&!state!.winner;i++){
      const cmd=chooseAiCommand(state!,state!.campaignMission?'easy':aiDifficulty);
      if(!cmd||cmd.type==='endTurn'){state=applyAction(state!,{type:'endTurn'});break}
      const p=previewAction(state!,cmd);if(!p.valid)break;
      const before=state!;state=applyAction(state!,cmd);queueMotion(before,state,p.path,cmd.unitId);noteDamage(before,state);
      activePulse={x:'x'in cmd?cmd.x:0,y:'y'in cmd?cmd.y:0,kind:cmd.type,at:performance.now()};tone(cmd.type==='move'?310:165,.1,'triangle');save();updateHUD();
      const motion=motions.get(cmd.unitId);await new Promise(r=>setTimeout(r,reduceMotion?70:Math.max(100,motion?.duration??230/animationSpeed)));
    }
    if(epoch!==battleEpoch||screen!=='battle'||modal||replayMode)return;
    if(current()&&!state!.winner)state=applyAction(state!,{type:'endTurn'});
    save();if(state?.winner){finishMatch();return}renderBattle();
  }catch(err){console.warn('AI order',err)}
  finally{if(runningAiEpoch===epoch)runningAiEpoch=null;if(epoch===battleEpoch&&screen==='battle'&&!modal&&state?.team==='red'&&!state.winner)setTimeout(runAI,200/animationSpeed)}
}
