  document.querySelector('#touch-confirm')?.addEventListener('click',()=>{const order=touchOrder;if(!order||!playerCanAct()||state!==order.state)return;touchOrder=null;commit(order.command);updateHUD()});
  document.querySelector('#touch-clear')?.addEventListener('click',()=>{touchOrder=null;selected=null;hovered=null;preview=null;moveCells=[];updateHUD()});
  document.querySelector('#touch-ground')?.addEventListener('click',()=>{touchGround=!touchGround;touchOrder=null;hovered=null;preview=null;updateHUD()});
  document.querySelector('#touch-bridge')?.addEventListener('click',()=>{touchBridge=!touchBridge;shiftHeld=touchBridge;actionMode='attack';touchOrder=null;hovered=null;preview=null;updateHUD()});
