  const selfAbility=actor?.id===target?.id&&actionMode==='ability';
  if(target&&(!actor||target.team===state.team&&!selfAbility&&!reinforcing(actor,tileAt(hovered.x,hovered.y)))){
    selected=target.id;actionMode='attack';moveCells=isMine(target)?legalMoves(state,target.id):[];preview=null;updateHUD();tone(525);return;
  }
  updatePreview();if(playerCanAct()&&preview?.valid&&actor&&['move','attack','ability'].includes(preview.type))touchOrder={command:{type:preview.type,unitId:actor.id,x:hovered.x,y:hovered.y} as Command,state,mode:actionMode};
